import json,tempfile,logging
from pathlib import Path
from huey import SqliteHuey
from huey.exceptions import TaskException
from huey.signals import SIGNAL_ERROR
logging.disable(logging.CRITICAL)
out={}
with tempfile.TemporaryDirectory() as tmp:
 for enabled in (True,False):
  filename=str(Path(tmp)/('results-%s.db'%enabled))
  h=SqliteHuey('demand-audit',filename=filename,results=enabled)
  delivered=[];fixed=[False];terminal_payloads=[]
  @h.task(name='send_email',retries=1,retry_delay=0)
  def send_email(subject,body,to):
   if not fixed[0]:raise RuntimeError('mail provider unavailable')
   delivered.append(to);return 'sent'
  @h.signal(SIGNAL_ERROR)
  def observe_terminal(signal,task,exc):
   if task.retries==0:terminal_payloads.append(h.serialize_task(task))
  task=send_email.s('Receipt','body','customer@example.invalid')
  original_id=task.id;handle=h.enqueue(task)
  attempts=0
  while h.pending_count():
   h.execute(h.dequeue());attempts+=1
  fresh=SqliteHuey('demand-audit',filename=filename,results=enabled)
  state={'attempts':attempts,'pending_after_exhaustion':fresh.pending_count(),'scheduled_after_exhaustion':fresh.scheduled_count(),'result_count_after_exhaustion':fresh.result_count(),'native_archive_api':hasattr(fresh,'failures'),'native_redrive_api':hasattr(fresh,'redrive'),'terminal_errors_observed_via_existing_signal':len(terminal_payloads),'signal_payload_preserves_args':h.deserialize_task(terminal_payloads[0]).args==task.args}
  if enabled:
   error=fresh.get(original_id,peek=True)
   state['stored_error_type']=type(error).__name__
   state['stored_error_fields']=sorted(error.metadata)
   state['stored_error_includes_invocation']=any(k in error.metadata for k in ('args','kwargs','data'))
   try:fresh.result(original_id)
   except TaskException:pass
   state['result_count_after_read']=fresh.result_count()
   fixed[0]=True
   one=handle.reschedule();two=handle.reschedule()
   state['retained_handle_reschedule_control']={'distinct_replacement_ids':one.id!=two.id,'pending':h.pending_count()}
   while h.pending_count():h.execute(h.dequeue())
   state['delivered_after_manual_repair']=len(delivered)
  out[str(enabled)]=state
print(json.dumps({'unmodified_upstream_reproduction':out},indent=2))
